-- ---------------------------------------------------------------------------
-- routes (B5 Recommended Routes) — static, team-curated catalog
-- ---------------------------------------------------------------------------
-- B5.1 [Recommended]: routes are pre-built from OpenStreetMap and stored in
-- our own database; the app only reads this table. Rows come from
-- supabase/seed_routes.sql, generated by scripts/build-route-seed.mjs.
-- OSM data is © OpenStreetMap contributors (ODbL) — the app shows that
-- attribution under the route cards.

create table public.routes (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  -- Figma chip labels: Loop / One-way (spec B5 calls them Turnaround / One way)
  type text not null check (type in ('loop', 'one_way')),
  distance_km numeric not null check (distance_km > 0),
  elevation_gain_m integer check (elevation_gain_m >= 0),
  start_lat double precision not null,
  start_lng double precision not null,
  -- Array of line segments, each an array of {lat, lng}. OSM routes are
  -- built from separate ways that don't always join into one line.
  path jsonb not null,
  source text not null default 'osm',
  source_id text, -- e.g. OSM relation id
  created_at timestamptz not null default now()
);

alter table public.routes enable row level security;

create policy "routes catalog is readable by signed-in users"
  on public.routes for select
  to authenticated
  using (true);
